/**
 * Markdown → self-contained HTML for dsh-session-md.
 *
 * The Markdown here is generated by `lib/render.mjs`, so the accepted grammar
 * is a fixed subset: ATX headings, pipe tables, fenced code, blockquotes,
 * ordered/unordered lists, horizontal rules, our own `<details>` sections, and
 * inline code / bold / italics / links. Everything else is escaped text.
 *
 * The output is one file with inline CSS — no external requests — that reads
 * well in light and dark themes and prints correctly: `<details>` sections are
 * expanded for print, so "HTML → browser print → Save as PDF" keeps the
 * reasoning and tool-call sections instead of printing empty summaries.
 */

/** Escape text for HTML, leaving existing entities (`&lt;`, `&#39;`, …) intact. */
function escapeHtml(text) {
  return String(text ?? '')
    .replace(/&(?!(?:[a-zA-Z][a-zA-Z0-9]*|#\d+|#[xX][0-9a-fA-F]+);)/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

/** Inline Markdown → HTML (input must already be escaped). */
function inline(text) {
  return String(text ?? '')
    // `code` first, so its content is not re-processed.
    .replace(/`([^`]+)`/g, (_match, code) => `<code>${code}</code>`)
    .replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>')
    .replace(/(^|[\s(（])\*([^*\n]+)\*/g, '$1<em>$2</em>')
    .replace(/\[([^\]]+)\]\(([^)\s]+)\)/g, (_match, label, href) => {
      const safe = /^(https?:|mailto:|#|\/|\.\/)/i.test(href) ? href : '#';
      return `<a href="${safe}" rel="noopener noreferrer">${label}</a>`;
    });
}

/** Split one line into a pipe-table row, or `undefined`. */
function tableCells(line) {
  const trimmed = line.trim();
  if (!trimmed.startsWith('|') || !trimmed.endsWith('|')) return undefined;
  return trimmed.slice(1, -1).split('|').map((cell) => cell.trim());
}

/** Whether a pipe-table row is the `|---|---|` separator. */
function isTableSeparator(line) {
  const cells = tableCells(line);
  return cells !== undefined && cells.length > 0 && cells.every((cell) => /^:?-{2,}:?$/.test(cell));
}

/** Fence marker of a line, when it opens or closes a code block. */
function fenceOf(line) {
  const match = /^(`{3,}|~{3,})\s*([\w+-]*)\s*$/.exec(line);
  return match === null ? undefined : { marker: match[1], language: match[2] };
}

/**
 * Render Markdown to the HTML body (no document skeleton).
 * @param {string} markdown - document produced by `renderSession`.
 * @returns {string} HTML fragment.
 */
export function markdownToHtmlBody(markdown) {
  const lines = String(markdown ?? '').split('\n');
  const out = [];
  let index = 0;

  while (index < lines.length) {
    const line = lines[index];

    // Fenced code
    const fence = fenceOf(line);
    if (fence !== undefined && !line.trim().startsWith('|')) {
      const body = [];
      index += 1;
      while (index < lines.length) {
        const closing = fenceOf(lines[index]);
        if (closing !== undefined && closing.marker[0] === fence.marker[0] && closing.marker.length >= fence.marker.length) break;
        body.push(lines[index]);
        index += 1;
      }
      index += 1;
      const language = fence.language === '' ? '' : ` class="language-${escapeHtml(fence.language)}"`;
      out.push(`<pre><code${language}>${escapeHtml(body.join('\n'))}</code></pre>`);
      continue;
    }

    // Our own collapsible sections pass through as raw HTML.
    if (/^<\/?details|^<summary/.test(line.trim())) {
      out.push(line.trim());
      index += 1;
      continue;
    }

    // Heading
    const heading = /^(#{1,6})\s+(.*)$/.exec(line);
    if (heading !== null) {
      const level = heading[1].length;
      out.push(`<h${level}>${inline(escapeHtml(heading[2]))}</h${level}>`);
      index += 1;
      continue;
    }

    // Pipe table
    if (tableCells(line) !== undefined && index + 1 < lines.length && isTableSeparator(lines[index + 1])) {
      const header = tableCells(line);
      index += 2;
      const rows = [];
      while (index < lines.length && tableCells(lines[index]) !== undefined) {
        rows.push(tableCells(lines[index]));
        index += 1;
      }
      const head = header.map((cell) => `<th>${inline(escapeHtml(cell))}</th>`).join('');
      const body = rows
        .map((cells) => `<tr>${cells.map((cell) => `<td>${inline(escapeHtml(cell))}</td>`).join('')}</tr>`)
        .join('');
      out.push(`<table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table>`);
      continue;
    }

    // Horizontal rule
    if (/^\s*([-*_])\1{2,}\s*$/.test(line)) {
      out.push('<hr>');
      index += 1;
      continue;
    }

    // Lists (consecutive items of one kind)
    if (/^\s*([-*]|\d+\.)\s+/.test(line)) {
      const ordered = /^\s*\d+\.\s+/.test(line);
      const items = [];
      while (index < lines.length && /^\s*([-*]|\d+\.)\s+/.test(lines[index])) {
        items.push(lines[index].replace(/^\s*([-*]|\d+\.)\s+/, ''));
        index += 1;
      }
      const tag = ordered ? 'ol' : 'ul';
      out.push(`<${tag}>${items.map((item) => {
        const checkbox = /^\[([ xX])\]\s+(.*)$/.exec(item);
        if (checkbox === null) return `<li>${inline(escapeHtml(item))}</li>`;
        const checked = checkbox[1].toLowerCase() === 'x' ? ' checked' : '';
        return `<li class="task"><input type="checkbox" disabled${checked}> ${inline(escapeHtml(checkbox[2]))}</li>`;
      }).join('')}</${tag}>`);
      continue;
    }

    // Blockquote
    if (/^\s*>/.test(line)) {
      const quoted = [];
      while (index < lines.length && /^\s*>/.test(lines[index])) {
        quoted.push(lines[index].replace(/^\s*>\s?/, ''));
        index += 1;
      }
      out.push(`<blockquote>${quoted.map((entry) => inline(escapeHtml(entry))).join('<br>')}</blockquote>`);
      continue;
    }

    // Blank line
    if (line.trim() === '') {
      index += 1;
      continue;
    }

    // Paragraph: consume until a blank line or a block opener.
    const paragraph = [];
    while (index < lines.length) {
      const current = lines[index];
      if (current.trim() === '') break;
      if (/^(#{1,6})\s+/.test(current) || /^\s*>/.test(current) || /^\s*([-*]|\d+\.)\s+/.test(current)) break;
      if (fenceOf(current) !== undefined) break;
      if (/^<\/?details|^<summary/.test(current.trim())) break;
      if (tableCells(current) !== undefined && isTableSeparator(lines[index + 1] ?? '')) break;
      paragraph.push(current);
      index += 1;
    }
    if (paragraph.length > 0) out.push(`<p>${inline(escapeHtml(paragraph.join('\n'))).replace(/\n/g, '<br>')}</p>`);
  }

  return out.join('\n');
}

/** Page-level CSS: theme tokens, typography, tables, collapsibles, print rules. */
const STYLE = `
:root{color-scheme:light dark;--bg:#fff;--fg:#1a1a1a;--muted:#5c5c5c;--line:#e3e3e3;--code-bg:#f6f7f9;--quote:#f4f5f7;--accent:#2652d6}
@media (prefers-color-scheme:dark){:root{--bg:#1c1d1f;--fg:#e8e8e8;--muted:#a0a0a0;--line:#333438;--code-bg:#26272b;--quote:#242528;--accent:#7aa2ff}}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--fg);font:16px/1.7 -apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif}
main{max-width:860px;margin:0 auto;padding:48px 28px 96px}
h1{font-size:28px;line-height:1.35;margin:0 0 20px}
h2{font-size:22px;line-height:1.4;margin:44px 0 14px;padding-top:14px;border-top:1px solid var(--line)}
h3{font-size:18px;margin:28px 0 10px}
h4,h5,h6{font-size:16px;margin:20px 0 8px}
p{margin:12px 0}
a{color:var(--accent)}
code{font:13px/1.5 ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;background:var(--code-bg);padding:2px 5px;border-radius:4px}
pre{background:var(--code-bg);border:1px solid var(--line);border-radius:8px;padding:12px 14px;overflow:auto}
pre code{background:none;padding:0;font-size:12.5px;white-space:pre-wrap;word-break:break-word}
table{border-collapse:collapse;margin:16px 0;width:100%;font-size:14px}
th,td{border:1px solid var(--line);padding:7px 10px;text-align:left;vertical-align:top}
th{background:var(--quote);font-weight:600}
blockquote{margin:14px 0;padding:10px 14px;background:var(--quote);border-left:3px solid var(--line);color:var(--muted)}
ul,ol{margin:12px 0;padding-left:26px}
li{margin:4px 0}
li.task{list-style:none;margin-left:-22px}
hr{border:none;border-top:1px solid var(--line);margin:28px 0}
details{margin:14px 0;border:1px solid var(--line);border-radius:8px;padding:8px 14px;background:linear-gradient(0deg,transparent,transparent)}
details>summary{cursor:pointer;color:var(--muted);font-size:14px}
details[open]>summary{margin-bottom:10px}
.toolbar{position:sticky;top:0;display:flex;justify-content:flex-end;gap:8px;padding:10px 28px;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(6px);border-bottom:1px solid var(--line)}
.toolbar button{font:13px/1 inherit;color:var(--fg);background:var(--code-bg);border:1px solid var(--line);border-radius:6px;padding:6px 10px;cursor:pointer}
@media print{
  :root{--bg:#fff;--fg:#000;--muted:#444;--line:#bbb;--code-bg:#f4f4f4;--quote:#f7f7f7;--accent:#000}
  .toolbar{display:none}
  main{max-width:none;padding:0}
  body{font-size:11.5pt}
  a{text-decoration:none}
  details{border-color:#bbb;break-inside:avoid}
  details>summary{font-weight:600}
  details>*:not(summary){display:block !important}
  details::details-content{content-visibility:visible !important}
  h2{break-after:avoid}
  pre,table,blockquote{break-inside:avoid}
}
`;

/** Small inline script: one button to open/close every collapsible section. */
const SCRIPT = `(function () {
  var button = document.getElementById('toggle-details');
  if (!button) return;
  button.addEventListener('click', function () {
    var sections = document.querySelectorAll('details');
    var anyClosed = false;
    sections.forEach(function (section) { if (!section.open) anyClosed = true; });
    sections.forEach(function (section) { section.open = anyClosed; });
    button.textContent = anyClosed ? '全部折叠' : '全部展开';
  });
})();`;

/**
 * Wrap a rendered Markdown document into one self-contained HTML page.
 * @param {object} input
 * @param {string} input.markdown - document from `renderSession`.
 * @param {string} [input.title] - page title; defaults to the first heading.
 * @param {string} [input.locale] - `<html lang>` value; defaults to `zh-CN`.
 * @returns {string} complete HTML document.
 */
export function markdownToHtml({ markdown, title, locale = 'zh-CN' } = {}) {
  const body = markdownToHtmlBody(markdown);
  const heading = /^#\s+(.*)$/m.exec(String(markdown ?? ''));
  const pageTitle = title ?? (heading === null ? '会话导出' : heading[1]);
  return `<!doctype html>
<html lang="${escapeHtml(locale)}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>${escapeHtml(pageTitle)}</title>
<style>${STYLE}</style>
</head>
<body>
<div class="toolbar"><button id="toggle-details" type="button">全部展开</button></div>
<main>
${body}
</main>
<script>${SCRIPT}</script>
</body>
</html>
`;
}
